// Package difftool computes and displays unified diffs between two pieces of text.
package difftool

import (
	"fmt"
	"io"
	"strings"

	"github.com/pmezard/go-difflib/difflib"
)

// Options controls how a unified diff is produced.
type Options struct {
	// FromFile and ToFile are the labels shown in the --- and +++ headers.
	FromFile string
	ToFile   string
	// FromDate and ToDate are optional timestamps shown after the headers.
	FromDate string
	ToDate   string
	// Context is the number of unchanged lines shown around each change.
	// Values less than zero are treated as zero.
	Context int
}

// Unified returns the unified diff between the two texts using opts.
// ...
func Unified(from, to string, opts Options) (string, error) {
	if opts.Context < 0 {
		opts.Context = 0
	}
	diff := difflib.UnifiedDiff{
		A:        difflib.SplitLines(from),
		B:        difflib.SplitLines(to),
		FromFile: opts.FromFile,
		ToFile:   opts.ToFile,
		FromDate: opts.FromDate,
		ToDate:   opts.ToDate,
		Context:  opts.Context,
	}
	return difflib.GetUnifiedDiffString(diff)
}

// WriteUnified writes ...
func WriteUnified(w io.Writer, from, to string, opts Options) error {
	s, err := Unified(from, to, opts)
	if err != nil {
		return err
	}
	_, err = io.WriteString(w, s)
	return err
}

// Equal reports whether two texts are identical.
func Equal(from, to string) bool { return from == to }
```

